def stateless_filter(rules, packet):
    for rule in rules:
        if packet["dst_port"] == rule["port"] and packet["proto"] == rule["proto"]:
            return rule["action"]
    return "deny"


rules = [
    {"proto": "tcp", "port": 443, "action": "allow"},
    {"proto": "tcp", "port": 22, "action": "allow"},
]


def stateful_filter(connection_table, rules, packet):
    key = (packet["src"], packet["dst"], packet["dst_port"], packet["proto"])
    if packet["flags"] == "SYN":
        decision = stateless_filter(rules, packet)
        if decision == "allow":
            connection_table.add(key)
        return decision
    if packet["flags"] == "ACK":
        return "allow" if key in connection_table else "deny"
    return "deny"


connection_table = set()
packets = [
    {"src": "10.0.0.5", "dst": "10.0.0.80", "dst_port": 443, "proto": "tcp", "flags": "SYN"},
    {"src": "10.0.0.5", "dst": "10.0.0.80", "dst_port": 443, "proto": "tcp", "flags": "ACK"},
    {"src": "10.0.0.9", "dst": "10.0.0.80", "dst_port": 443, "proto": "tcp", "flags": "ACK"},
]

for packet in packets:
    decision = stateful_filter(connection_table, rules, packet)
    print(f"{packet['src']}->{packet['dst']}:{packet['dst_port']} {packet['flags']}: {decision}")
